SELECT COUNT(*)
FROM tb_tenant_database
WHERE db_name = #{value}

SELECT COALESCE(NULLIF(TRIM(onboarding_status), ''), 'EMAIL_QUEUED')
FROM tb_tenant
WHERE tenant_code = #{value}

SELECT tenant_nm
FROM tb_tenant
WHERE tenant_code = #{value}

SELECT login_code
FROM tb_login_account
WHERE login_id = #{value}

SELECT admin_email
FROM tb_tenant
WHERE tenant_code = #{value}

